
// ═══ retro sound (Web Audio, no files) ═══
let audioCtx = null;
let soundOn = true;
function ensureAudio() {
  if (!audioCtx) { try { audioCtx = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { audioCtx = null; } }
  if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
}
function tone(freq, start, dur, type, gainVal) {
  if (!audioCtx) return;
  const osc = audioCtx.createOscillator(); const gain = audioCtx.createGain();
  osc.type = type || 'square';
  osc.frequency.setValueAtTime(freq, audioCtx.currentTime + start);
  gain.gain.setValueAtTime(0, audioCtx.currentTime + start);
  gain.gain.linearRampToValueAtTime(gainVal || 0.22, audioCtx.currentTime + start + 0.01);
  gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + start + dur);
  osc.connect(gain).connect(audioCtx.destination);
  osc.start(audioCtx.currentTime + start); osc.stop(audioCtx.currentTime + start + dur + 0.02);
}
function playStartJingle() {
  if (!soundOn) return;
  ensureAudio();
  const osc = audioCtx.createOscillator(); const gain = audioCtx.createGain();
  osc.type = 'square';
  const t0 = audioCtx.currentTime;
  osc.frequency.setValueAtTime(220, t0);
  osc.frequency.exponentialRampToValueAtTime(660, t0 + 0.12);
  gain.gain.setValueAtTime(0.001, t0);
  gain.gain.linearRampToValueAtTime(0.19, t0 + 0.02);
  gain.gain.exponentialRampToValueAtTime(0.001, t0 + 0.13);
  osc.connect(gain).connect(audioCtx.destination);
  osc.start(t0); osc.stop(t0 + 0.14);
  tone(523, 0.14, 0.09, 'square', 0.20);
  tone(659, 0.22, 0.09, 'square', 0.20);
  tone(784, 0.30, 0.09, 'square', 0.21);
  tone(1046, 0.38, 0.30, 'square', 0.23);
}
function playConfirmBlip() {
  if (!soundOn) return;
  ensureAudio();
  tone(660, 0,    0.08, 'sine', 0.17);
  tone(880, 0.05, 0.16, 'triangle', 0.16);
}

const SFX_VICTORY_SRC = 'data:audio/mpeg;base64,';
const SFX_SKIP_PENALTY_SRC = 'data:audio/mpeg;base64,';
function playAudioClip(src, volume) {
  if (!soundOn) return;
  try {
    const a = new Audio(src);
    a.volume = volume != null ? volume : 0.6;
    a.play().catch(() => {});
  } catch (e) {}
}

// pleasant "got it" chime — two gentle sine/triangle notes rising
// a major third, no harsh edges, but clearly audible
function playCoinSound() {
  if (!soundOn) return;
  ensureAudio();
  tone(784,  0,    0.10, 'sine', 0.20);
  tone(988,  0.07, 0.22, 'triangle', 0.19);
}

// "skip with penalty" cue — real retro "took damage" sound effect
function playHitSound() {
  playAudioClip(SFX_SKIP_PENALTY_SRC, 0.7);
}

// "skip, no penalty" cue — two flat, equal-pitch triangle taps (no
// melodic rise or fall), so it reads as neutral rather than good or bad,
// while staying loud and distinct from the Next/Play confirm blip
function playNeutralTick() {
  if (!soundOn) return;
  ensureAudio();
  tone(392, 0,    0.08, 'triangle', 0.24);
  tone(392, 0.10, 0.10, 'triangle', 0.22);
}
